@page "/courses"

@inject CourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Courses - University Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Course Catalog</h1>

    <form method="get" class="row g-3 mb-4">
        <div class="col-md-6">
            <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or instructor..." />
        </div>
        <div class="col-md-4">
            <select name="departmentId" class="form-select">
                <option value="">All Departments</option>
                @foreach (var dept in Departments)
                {
                    <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button type="submit" class="btn btn-primary w-100">Filter</button>
        </div>
    </form>

    @if (Courses.Count == 0)
    {
        <div class="alert alert-info">No courses match your search criteria.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Instructor</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in Courses)
                    {
                        <tr>
                            <td>@course.Code</td>
                            <td>@course.Title</td>
                            <td>@course.DepartmentName</td>
                            <td>@course.Credits</td>
                            <td>@course.InstructorName</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private IReadOnlyList<CourseCatalog.Models.Course> Courses { get; set; } = [];
    private IReadOnlyList<CourseCatalog.Models.Department> Departments { get; set; } = [];

    protected override void OnInitialized()
    {
        Departments = CatalogService.GetDepartments();
        Courses = CatalogService.GetCourses(Search, DepartmentId);
    }
}

@page "/enroll"

@inject CourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (Submitted)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Enrollment Submitted!</h4>
            <p>Your enrollment request for <strong>@SelectedCourseName</strong> has been received. You will receive a confirmation via your university email.</p>
            <hr />
            <a href="/courses" class="btn btn-primary">Back to Catalog</a>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-lg-8">
                <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                    <DataAnnotationsValidator />
                    <AntiforgeryToken />

                    <div class="mb-3">
                        <label for="fullName" class="form-label">Full Name</label>
                        <InputText id="fullName" @bind-Value="Model.FullName" class="form-control" />
                        <ValidationMessage For="() => Model.FullName" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" />
                        <ValidationMessage For="() => Model.StudentId" />
                        <div class="form-text">Enter your 6-10 character alphanumeric student ID.</div>
                    </div>

                    <div class="mb-3">
                        <label for="courseId" class="form-label">Course</label>
                        <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                            <option value="0">-- Select a course --</option>
                            @foreach (var course in AllCourses)
                            {
                                <option value="@course.Id">@course.Code - @course.Title</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => Model.CourseId" />
                    </div>

                    <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                    <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    [SupplyParameterFromForm]
    private CourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private IReadOnlyList<CourseCatalog.Models.Course> AllCourses { get; set; } = [];
    private bool Submitted { get; set; }
    private string SelectedCourseName { get; set; } = string.Empty;

    protected override void OnInitialized()
    {
        AllCourses = CatalogService.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var success = CatalogService.SubmitEnrollment(Model);
        if (success)
        {
            var course = CatalogService.GetCourse(Model.CourseId);
            SelectedCourseName = course is not null ? $"{course.Code} - {course.Title}" : "Unknown Course";
            Submitted = true;
        }
    }
}

